def transform(grid):
    if not grid or not grid[0]:
        return grid
    result = [[0] * len(grid[0]) for _ in range(len(grid))]
    h, w = len(grid), len(grid[0])

    top, bottom, left, right = -1, -1, -1, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                if top == -1 or r < top: top = r
                if bottom == -1 or r > bottom: bottom = r
                if left == -1 or c < left: left = c
