    if top == -1:
        return result

    input_frames = []
    curr_t, curr_b, curr_l, curr_r = top, bottom, left, right
    while curr_t <= curr_b and curr_l <= curr_r:
        input_frames.append((curr_t, curr_b, curr_l, curr_r))
        curr_t += 1
        curr_b -= 1
        curr_l += 1
        curr_r -= 1

    # F0 stays same, others shrink
    output_frames = []
    for i, (it, ib, il, ir) in enumerate(input_frames):
        if i == 0:
            ot, ob, ol, or_ = it, ib, il, ir
        else:
            ot, ob, ol, or_ = it + 1, ib - 1, il + 1, ir - 1
        new_size = ob - ot + 1
        if ot <= ob and ol <= or_:
            border_flag = (new_size >= 4 or new_size == 2)
            output_frames.append((ot, ob, ol, or_, border_flag))

    # Draw frames
    for f_t, f_b, f_l, f_r, should_have_border in output_frames:
        if should_have_border:
            for r in range(f_t, f_b + 1):
                for c in range(f_l, f_r + 1):
                    if r == f_t or r == f_b or c == f_l or c == f_r:
                        result[r][c] = 5
        else:
            for r in range(f_t, f_b + 1):
                for c in range(f_l, f_r + 1):
                    result[r][c] = 0

    # Fill annular
    for i in range(len(output_frames) - 1):
        outer_t, outer_b, outer_l, outer_r, outer_hb = output_frames[i]
        inner_t, inner_b, inner_l, inner_r, inner_hb = output_frames[i + 1]

        for r in range(outer_t + 1, outer_b):
            for c in range(outer_l + 1, outer_r):
                if inner_t <= r <= inner_b and inner_l <= c <= inner_r:
                    continue
                result[r][c] = 2

    return result
